import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("cut history", () => {
  test("cut history", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-10"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-11", "to": "2026-03-20"})).toBe(true);
    await ui.setSetting(pg_uma, "pot", "10.00");
    expect(await ui.addPool(pg_uma, "P")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P", {"member": "Ada", "share": "50.00"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "P", {"member": "Ben", "share": "50.00"})).toBe(true);
    await ui.setToday(pg_uma, "2026-03-11");
    await ui.setSetting(pg_uma, "pot", "20.00");
    expect(await ui.hold(pg_uma, p_ben, {"from": "2026-03-11"})).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("pool-row-P").getByTestId("pool-total-share")).toHaveText("100.00");
    await expect(pg_uma.getByTestId("pool-row-P").getByTestId("pool-balanced")).toHaveText("yes");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-share")).toHaveText("50.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-cut")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-cut-P1")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-share")).toHaveText("50.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-cut")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-cut-P1")).toHaveText("5.00");
    await ui.setToday(pg_uma, "2026-03-21");
    expect(await ui.addPoolMember(pg_uma, "P", {"member": "Ada", "share": "1.00"})).toBe(false);
    await ui.setSetting(pg_uma, "pot", "30.00");
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("pool-row-P").getByTestId("pool-total-share")).toHaveText("100.00");
    await expect(pg_uma.getByTestId("pool-row-P").getByTestId("pool-balanced")).toHaveText("yes");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-share")).toHaveText("50.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-cut")).toHaveText("30.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-cut-P1")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-cut-P2")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-share")).toHaveText("50.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-cut")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-cut-P1")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-cut-P2")).toHaveText("0.00");
    expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
    await ui.setSetting(pg_uma, "pot", "40.00");
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("pool-row-P").getByTestId("pool-total-share")).toHaveText("100.00");
    await expect(pg_uma.getByTestId("pool-row-P").getByTestId("pool-balanced")).toHaveText("yes");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-share")).toHaveText("50.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-cut")).toHaveText("40.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-cut-P1")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ada).getByTestId("pool-cut-P2")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-share")).toHaveText("50.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-cut")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-cut-P1")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("pool-member-P-" + p_ben).getByTestId("pool-cut-P2")).toHaveText("0.00");
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=12.50`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERIOD_ADDED sheet=${sheet} by=uma period=P1 from=2026-03-01 to=2026-03-10`,
      `PERIOD_ADDED sheet=${sheet} by=uma period=P2 from=2026-03-11 to=2026-03-20`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=pot value=10.00`,
      `POOL_ADDED sheet=${sheet} by=uma name=P`,
      `POOL_MEMBER_ADDED sheet=${sheet} by=uma pool=P name=Ada share=50.00`,
      `POOL_MEMBER_ADDED sheet=${sheet} by=uma pool=P name=Ben share=50.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=0.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=pot value=20.00`,
      `PERSON_HELD sheet=${sheet} by=uma name=Ben from=2026-03-11`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=0.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=pot value=30.00`,
      `PERIOD_CLOSED sheet=${sheet} by=uma period=P1 total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=pot value=40.00`
    ]);
  });
